let i = 0;
function pickRoundRobin(backends) {
  const chosen = backends[i % backends.length];
  i += 1;
  return chosen;   // ignores current load entirely
}

function pickLeastConnections(backends) {
  return backends.reduce((min, b) =>
    b.activeConnections < min.activeConnections ? b : min
  );
}

function onRequestStart(b) { b.activeConnections++; }
function onRequestEnd(b)   { b.activeConnections--; }

async function healthLoop(backend) {
  setInterval(async () => {
    try {
      const ok = await ping(backend, { timeoutMs: 2000 });
      backend.failures = ok ? 0 : backend.failures + 1;
    } catch {
      backend.failures += 1;
    }
    backend.healthy = backend.failures < 3;   // 3 strikes, not 1
  }, 5000);
}

function markUnhealthy(backend) {
  backend.healthy = false;          // no new traffic
  // existing in-flight requests are left alone to complete naturally
}

function pickSticky(backends, sessionKey) {
  const idx = hash(sessionKey) % backends.length;
  return backends[idx];   // same key -> same backend, as long as the set is stable
}
// caveat: adding/removing a backend reshuffles most keys — see consistent hashing
